import sys
from decimal import Decimal, ROUND_HALF_UP


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 3:
            continue
        a_str, op, b_str = parts
        try:
            a = Decimal(a_str)
            b = Decimal(b_str)
        except Exception:
            continue
        if op == "+":
            result = a + b
        elif op == "-":
            result = a - b
        elif op == "*":
            result = a * b
        elif op == "/":
            if b == 0:
                print("ERROR")
                continue
            result = (a / b).quantize(
                Decimal("1e-10"), rounding=ROUND_HALF_UP
            )
        else:
            continue
        # Format the output according to specification
        if result == int(result):
            print(str(int(result)))
        elif result < 0:
            print(f"{result}")
        else:
            parts = str(result).split(".")
            integer = parts[0].lstrip("0") or "0"
            fractional = parts[1].rstrip("0")
            if fractional:
                print(f"{integer}.{fractional}")
            else:
                print(integer)


if __name__ == "__main__":
    main()
